if(guildType > 3 || guildType == 0 || userGuildType[user] == guildType) {
revert("guildType");
}
culGuildTypeByAddNum[guildType] ++;
if(culGuildTypeByAddNum[guildType] > GuildTypeByMaxnum[guildType]) {
revert("culGuildTypeByAddNum");
